-- ----------------------------
-- Table structure for dy_shop_account
-- ----------------------------
DROP TABLE IF EXISTS `dy_shop_account`;
CREATE TABLE `dy_shop_account`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `store_pk` int NOT NULL,
  `balance` bigint NULL DEFAULT NULL,
  `withdraw_balance` bigint NULL DEFAULT NULL,
  `reserve_balance` bigint NULL DEFAULT NULL,
  `frozen_balance` bigint NULL DEFAULT NULL,
  `pending_settle` bigint NULL DEFAULT NULL,
  `settle_day` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `qianchuan_balance` bigint NULL DEFAULT NULL,
  `deposit_base` bigint NULL DEFAULT NULL,
  `deposit_experience` bigint NULL DEFAULT NULL,
  `bank_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `bank_tail` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `channel_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `channels_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `synced_at` datetime NULL DEFAULT NULL,
  `sync_error` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_dy_shop_account_store`(`store_pk` ASC) USING BTREE,
  CONSTRAINT `dy_shop_account_ibfk_1` FOREIGN KEY (`store_pk`) REFERENCES `dy_shop` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

